import { cache, Suspense } from 'react'
import { RevenueChart } from './RevenueChart'
import { LatestInvoices } from './LatestInvoices'
import { CardStats } from './CardStats'

type RevenuePoint = {
  month: string
  amount: number
}

type Invoice = {
  id: string
  name: string
  amount: number
}

type DashboardData = {
  totalRevenue: number
  totalInvoices: number
  revenue: RevenuePoint[]
  invoices: Invoice[]
}

const getDashboardData = cache(async (): Promise<DashboardData> => {
  const res = await fetch('https://api.example.com/dashboard', {
    cache: 'no-store',
  })

  if (!res.ok) {
    throw new Error('Failed to load dashboard data')
  }

  return res.json()
})

async function CardStatsSection() {
  const data = await getDashboardData()

  return (
    <CardStats
      totalRevenue={data.totalRevenue}
      totalInvoices={data.totalInvoices}
    />
  )
}

async function RevenueChartSection() {
  const { revenue } = await getDashboardData()

  return <RevenueChart revenue={revenue} />
}

async function LatestInvoicesSection() {
  const { invoices } = await getDashboardData()

  return <LatestInvoices invoices={invoices} />
}

function CardStatsFallback() {
  return (
    <div className="stats-grid" aria-hidden="true">
      <div className="card skeleton-card">
        <span className="skeleton skeleton-label" />
        <span className="skeleton skeleton-value" />
      </div>
      <div className="card skeleton-card">
        <span className="skeleton skeleton-label" />
        <span className="skeleton skeleton-value skeleton-value-short" />
      </div>
    </div>
  )
}

function RevenueChartFallback() {
  return (
    <section className="panel chart" aria-labelledby="revenue-title">
      <h2 id="revenue-title">Revenue</h2>
      <div className="chart-bars" aria-hidden="true">
        {[68, 44, 72, 53, 84, 61].map((height) => (
          <span
            className="skeleton chart-bar"
            key={height}
            style={{ height: `${height}%` }}
          />
        ))}
      </div>
    </section>
  )
}

function LatestInvoicesFallback() {
  return (
    <section className="panel invoices" aria-labelledby="invoices-title">
      <h2 id="invoices-title">Latest Invoices</h2>
      <ul aria-hidden="true">
        {['one', 'two', 'three', 'four'].map((item) => (
          <li key={item}>
            <span className="skeleton invoice-name" />
            <span className="skeleton invoice-amount" />
          </li>
        ))}
      </ul>
    </section>
  )
}

export default function Page() {
  return (
    <main className="dashboard">
      <header className="dashboard-header">
        <p>Overview</p>
        <h1>Dashboard</h1>
      </header>

      <Suspense fallback={<CardStatsFallback />}>
        <CardStatsSection />
      </Suspense>

      <div className="dashboard-grid">
        <Suspense fallback={<RevenueChartFallback />}>
          <RevenueChartSection />
        </Suspense>
        <Suspense fallback={<LatestInvoicesFallback />}>
          <LatestInvoicesSection />
        </Suspense>
      </div>
    </main>
  )
}
* {
  box-sizing: border-box;
}

:root {
  color: #172033;
  background: #f6f7f9;
  font-family:
    Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI",
    sans-serif;
}

body {
  margin: 0;
  min-height: 100vh;
  background: #f6f7f9;
}

.dashboard {
  width: min(1120px, calc(100% - 32px));
  margin: 0 auto;
  padding: 40px 0;
}

.dashboard-header {
  margin-bottom: 24px;
}

.dashboard-header p {
  margin: 0 0 6px;
  color: #5c667a;
  font-size: 0.875rem;
  font-weight: 700;
  text-transform: uppercase;
}

.dashboard-header h1 {
  margin: 0;
  color: #101828;
  font-size: clamp(2rem, 4vw, 3rem);
  line-height: 1;
}

.stats-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 16px;
  margin-bottom: 16px;
}

.dashboard-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.35fr) minmax(320px, 0.65fr);
  gap: 16px;
  align-items: start;
}

.card,
.panel {
  border: 1px solid #dce3eb;
  border-radius: 8px;
  background: #ffffff;
  box-shadow: 0 1px 2px rgba(16, 24, 40, 0.05);
}

.card {
  min-height: 132px;
  padding: 20px;
}

.card h2,
.panel h2 {
  margin: 0;
  color: #475467;
  font-size: 0.875rem;
  font-weight: 700;
}

.card p {
  margin: 18px 0 0;
  color: #101828;
  font-size: 2rem;
  font-weight: 750;
  line-height: 1.1;
}

.panel {
  min-height: 360px;
  padding: 20px;
}

.chart-list,
.invoices ul {
  display: grid;
  gap: 14px;
  margin: 20px 0 0;
  padding: 0;
  list-style: none;
}

.chart-list li {
  display: grid;
  grid-template-columns: 48px 96px 1fr;
  gap: 12px;
  align-items: center;
  min-height: 28px;
  color: #344054;
  font-size: 0.9375rem;
}

.chart-meter {
  display: block;
  height: 10px;
  border-radius: 999px;
  background: #2f6fed;
}

.invoices li {
  display: flex;
  min-height: 42px;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  border-bottom: 1px solid #eef2f6;
  color: #344054;
}

.invoices li:last-child {
  border-bottom: 0;
}

.invoices strong {
  color: #101828;
}

.skeleton {
  display: block;
  overflow: hidden;
  border-radius: 999px;
  background: linear-gradient(90deg, #e5e9f0 25%, #f2f4f7 37%, #e5e9f0 63%);
  background-size: 400% 100%;
  animation: skeleton-pulse 1.4s ease infinite;
}

.skeleton-card {
  display: grid;
  align-content: start;
  gap: 20px;
}

.skeleton-label {
  width: 132px;
  height: 16px;
}

.skeleton-value {
  width: 220px;
  max-width: 80%;
  height: 38px;
  border-radius: 8px;
}

.skeleton-value-short {
  width: 92px;
}

.chart-bars {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  align-items: end;
  gap: 12px;
  height: 276px;
  margin-top: 20px;
}

.chart-bar {
  min-height: 64px;
  border-radius: 8px 8px 0 0;
}

.invoice-name {
  width: 54%;
  height: 16px;
}

.invoice-amount {
  width: 84px;
  height: 16px;
}

@keyframes skeleton-pulse {
  0% {
    background-position: 100% 50%;
  }

  100% {
    background-position: 0 50%;
  }
}

@media (max-width: 760px) {
  .dashboard {
    width: min(100% - 24px, 1120px);
    padding: 28px 0;
  }

  .stats-grid,
  .dashboard-grid {
    grid-template-columns: 1fr;
  }

  .chart-list li {
    grid-template-columns: 44px 88px 1fr;
  }
}

import { cache, Suspense } from 'react'
import { RevenueChart } from './RevenueChart'
import { LatestInvoices } from './LatestInvoices'
import { CardStats } from './CardStats'
import {
  CardStatsFallback,
  DashboardHeader,
  LatestInvoicesFallback,
  RevenueChartFallback,
} from './DashboardShell'

type RevenuePoint = {
  month: string
  amount: number
}

type Invoice = {
  id: string
  name: string
  amount: number
}

type DashboardData = {
  totalRevenue: number
  totalInvoices: number
  revenue: RevenuePoint[]
  invoices: Invoice[]
}

const getDashboardData = cache(async (): Promise<DashboardData> => {
  const res = await fetch('https://api.example.com/dashboard', {
    cache: 'no-store',
  })

  if (!res.ok) {
    throw new Error('Failed to load dashboard data')
  }

  return res.json()
})

async function CardStatsSection() {
  const data = await getDashboardData()

  return (
    <CardStats
      totalRevenue={data.totalRevenue}
      totalInvoices={data.totalInvoices}
    />
  )
}

async function RevenueChartSection() {
  const { revenue } = await getDashboardData()

  return <RevenueChart revenue={revenue} />
}

async function LatestInvoicesSection() {
  const { invoices } = await getDashboardData()

  return <LatestInvoices invoices={invoices} />
}

export default function Page() {
  return (
    <main className="dashboard">
      <DashboardHeader />

      <Suspense fallback={<CardStatsFallback />}>
        <CardStatsSection />
      </Suspense>

      <div className="dashboard-grid">
        <Suspense fallback={<RevenueChartFallback />}>
          <RevenueChartSection />
        </Suspense>
        <Suspense fallback={<LatestInvoicesFallback />}>
          <LatestInvoicesSection />
        </Suspense>
      </div>
    </main>
  )
}
export function DashboardHeader() {
  return (
    <header className="dashboard-header">
      <p>Overview</p>
      <h1>Dashboard</h1>
    </header>
  )
}

export function CardStatsFallback() {
  return (
    <div className="stats-grid" aria-hidden="true">
      <div className="card skeleton-card">
        <span className="skeleton skeleton-label" />
        <span className="skeleton skeleton-value" />
      </div>
      <div className="card skeleton-card">
        <span className="skeleton skeleton-label" />
        <span className="skeleton skeleton-value skeleton-value-short" />
      </div>
    </div>
  )
}

export function RevenueChartFallback() {
  return (
    <section className="panel chart" aria-labelledby="revenue-title">
      <h2 id="revenue-title">Revenue</h2>
      <div className="chart-bars" aria-hidden="true">
        {[68, 44, 72, 53, 84, 61].map((height, index) => (
          <span
            className="skeleton chart-bar"
            key={`${height}-${index}`}
            style={{ height: `${height}%` }}
          />
        ))}
      </div>
    </section>
  )
}

export function LatestInvoicesFallback() {
  return (
    <section className="panel invoices" aria-labelledby="invoices-title">
      <h2 id="invoices-title">Latest Invoices</h2>
      <ul aria-hidden="true">
        {['one', 'two', 'three', 'four'].map((item) => (
          <li key={item}>
            <span className="skeleton invoice-name" />
            <span className="skeleton invoice-amount" />
          </li>
        ))}
      </ul>
    </section>
  )
}

export function DashboardFallbackShell() {
  return (
    <main className="dashboard" aria-busy="true">
      <DashboardHeader />
      <CardStatsFallback />
      <div className="dashboard-grid">
        <RevenueChartFallback />
        <LatestInvoicesFallback />
      </div>
    </main>
  )
}
export function RevenueChart({
  revenue,
}: {
  revenue: { month: string; amount: number }[]
}) {
  const maxRevenue = Math.max(...revenue.map((item) => item.amount), 1)

  return (
    <section className="panel chart" aria-labelledby="revenue-title">
      <h2 id="revenue-title">Revenue</h2>
      <ul className="chart-list">
        {revenue.map((item) => (
          <li key={item.month}>
            <span>{item.month}</span>
            <span>${item.amount.toLocaleString()}</span>
            <span
              className="chart-meter"
              style={{ width: `${(item.amount / maxRevenue) * 100}%` }}
            />
          </li>
        ))}
      </ul>
    </section>
  )
}
export function LatestInvoices({
  invoices,
}: {
  invoices: { id: string; name: string; amount: number }[]
}) {
  return (
    <section className="panel invoices" aria-labelledby="invoices-title">
      <h2 id="invoices-title">Latest Invoices</h2>
      <ul>
        {invoices.map((invoice) => (
          <li key={invoice.id}>
            <span>{invoice.name}</span>
            <strong>${invoice.amount.toLocaleString()}</strong>
          </li>
        ))}
      </ul>
    </section>
  )
}

